// Settings: ONE place for all numbers and rules of Workflow B.
// Why: Stage 2 and Stage 3 rules are easy to tune here. It also reads and checks batch_id.
const body = $('Webhook').first().json.body || {};
const batchId = String(body.batch_id || '');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(batchId)) {
  throw new Error('batch_id is missing or not a UUID');
}

const cfg = {
  loanAmount: 300000,        // standard loan amount used for the EMI check (rupees)
  tenureMonths: 36,          // fixed 3 year tenure
  maxEmiShare: 0.40,         // EMI must be at most 40% of monthly income
  rateBrackets: [{ maxRate: 10, minIncome: 40000 }],  // low-rate loans need a higher income
  nearPct: 1.05,             // "borderline" = within 5% above a threshold
  llmMaxPairs: 100,          // max NEW pairs sent to the LLM per run (keeps demo cheap)
  llmBatchSize: 20,          // users per LLM call
  llmUrl: 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions',
  hiddenCriteria: '(years? old|years? of|experience|tax|itr|turnover|vintage|existing|resident|employer|bank statement)',
};

const A = Number(cfg.loanAmount), N = Number(cfg.tenureMonths);
const emi = `CASE WHEN p.interest_rate IS NULL THEN NULL
  WHEN p.interest_rate = 0 THEN ${A}::numeric / ${N}
  ELSE ${A}::numeric * (p.interest_rate/1200) * power(1 + p.interest_rate/1200, ${N}) / (power(1 + p.interest_rate/1200, ${N}) - 1) END`;
const brackets = cfg.rateBrackets
  .map(b => `(p.interest_rate <= ${Number(b.maxRate)} AND u.monthly_income < ${Number(b.minIncome)})`).join(' OR ') || 'false';

// Stage 2 SQL: delete pairs that fail the rules, mark the rest as 'rules', record after_rules.
const sqlRules = `WITH calc AS (
  SELECT m.match_id, u.monthly_income, ${emi} AS emi, coalesce(${brackets}, false) AS low_rate_fail
  FROM matches m
  JOIN users u ON u.user_id = m.user_id
  JOIN loan_products p ON p.product_id = m.product_id
  WHERE m.batch_id = $1::uuid
), bad AS (
  SELECT match_id FROM calc WHERE (emi IS NOT NULL AND emi > ${Number(cfg.maxEmiShare)} * monthly_income) OR low_rate_fail
), del AS (
  DELETE FROM matches WHERE match_id IN (SELECT match_id FROM bad) RETURNING match_id
), upd AS (
  UPDATE matches SET stage = 'rules' WHERE batch_id = $1::uuid AND match_id NOT IN (SELECT match_id FROM bad) RETURNING match_id
)
INSERT INTO pipeline_stats (batch_id, stage, pairs)
SELECT $1::uuid, 'after_rules', (SELECT count(*) FROM upd) RETURNING stage, pairs`;

// Stage 3 SQL: find borderline pairs, with any cached LLM answer. New pairs are capped.
const key = `md5(coalesce(p.raw_hash,'') || '|' || u.monthly_income::text || '|' || u.credit_score::text || '|' || u.age::text || '|' || lower(u.employment_status))`;
const sqlBorderline = `WITH b AS (
  SELECT m.user_id, m.product_id, p.product_name, p.raw_hash, p.eligibility_text,
         u.monthly_income, u.credit_score, u.age, lower(u.employment_status) AS employment,
         coalesce(p.eligibility_text ~* '${cfg.hiddenCriteria}', false) AS hidden_rule,
         ${key} AS cache_key
  FROM matches m
  JOIN users u ON u.user_id = m.user_id
  JOIN loan_products p ON p.product_id = m.product_id
  WHERE m.batch_id = $1::uuid
    AND ( coalesce(p.eligibility_text ~* '${cfg.hiddenCriteria}', false)
       OR (coalesce(p.min_monthly_income, 0) > 0 AND u.monthly_income < p.min_monthly_income * ${Number(cfg.nearPct)})
       OR (p.min_credit_score IS NOT NULL AND u.credit_score < p.min_credit_score * ${Number(cfg.nearPct)}) )
), x AS (
  SELECT b.*, c.result AS cached,
         row_number() OVER (PARTITION BY (c.result IS NULL) ORDER BY b.hidden_rule DESC, b.product_id, b.user_id) AS rn
  FROM b LEFT JOIN llm_cache c ON c.rule_hash = b.cache_key
)
SELECT * FROM x WHERE cached IS NOT NULL OR rn <= ${Number(cfg.llmMaxPairs)}`;

return [{ json: { batch_id: batchId, sql_rules: sqlRules, sql_borderline: sqlBorderline,
                  llm_url: cfg.llmUrl, batch_size: cfg.llmBatchSize } }];

// Group borderline applicants by rule hash and send at most 20 per request.
// Without an API key, safely skip new judgments; undecided pairs remain matched.
const s = $('Settings').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.user_id);
const fresh = rows.filter(r => !r.cached);
const apiKey = String($env.LLM_API_KEY || '').trim();
if (!apiKey) return [{ json: { dummy: true, skipReason: 'LLM_API_KEY is not configured' } }];

const byRule = new Map();
fresh.forEach(r => {
  const ruleKey = r.raw_hash || ('product:' + r.product_id);
  if (!byRule.has(ruleKey)) byRule.set(ruleKey, []);
  byRule.get(ruleKey).push(r);
});

const system = `You check loan eligibility. You get one loan product's eligibility text and a list of applicants.
Decide for each applicant if they meet ALL criteria in the text, using ONLY the applicant fields given.
If a criterion needs data that is not in the fields (for example business age), assume it is met.
Reply with JSON only, in exactly this shape: {"results":[{"user_id":"...","eligible":true}]}
Include every applicant exactly once. No other text.`;

const out = [];
for (const [ruleKey, list] of byRule) {
  for (let i = 0; i < list.length; i += s.batch_size) {
    const chunk = list.slice(i, i + s.batch_size);
    const keys = {};
    chunk.forEach(r => { keys[r.user_id] = r.cache_key; });
    const users = chunk.map(r => ({ user_id: r.user_id, monthly_income: Number(r.monthly_income),
      credit_score: Number(r.credit_score), age: Number(r.age), employment_status: r.employment }));
    const user = `Eligibility text: ${chunk[0].eligibility_text}\nApplicants: ${JSON.stringify(users)}`;
    out.push({ json: { llm_url: s.llm_url, rule_hash: ruleKey, keys,
      body: { model: $env.LLM_MODEL, temperature: 0, response_format: { type: 'json_object' },
              messages: [{ role: 'system', content: system }, { role: 'user', content: user }] } } });
  }
}
if (out.length === 0) out.push({ json: { dummy: true, skipReason: 'No uncached borderline pairs' } });
return out;

// Parse LLM answers: joins cached answers and new answers, then builds the SQL for
// (1) saving new answers in llm_cache, (2) deleting rejected pairs, (3) the stats rows.
// Why safe: bad JSON or a failed call is skipped. Undecided pairs stay (benefit of the doubt) and are not cached.
const rows = $('Find borderline').all().map(i => i.json).filter(r => r.user_id);
const plan = $('Plan LLM batches').all().map(i => i.json);
const answers = $input.all();
const q = s => "'" + String(s).replace(/'/g, "''") + "'";

const decided = new Map();   // cache_key -> true/false
rows.forEach(r => { if (r.cached && typeof r.cached.eligible === 'boolean') decided.set(r.cache_key, r.cached.eligible); });

const fresh = new Map();
let calls = 0, failed = 0;
if (!(plan.length === 1 && plan[0].dummy)) {
  answers.forEach((a, i) => {
    try {
      const text = String(a.json.choices[0].message.content).replace(/```json|```/g, '').trim();
      const data = JSON.parse(text);
      (Array.isArray(data.results) ? data.results : []).forEach(r => {
        const key = plan[i].keys[String(r.user_id)];
        if (key && typeof r.eligible === 'boolean') fresh.set(key, r.eligible);
      });
      calls += 1;
    } catch (e) { failed += 1; }
  });
}
fresh.forEach((v, k) => decided.set(k, v));

const rejected = [], accepted = [];
rows.forEach(r => {
  if (!decided.has(r.cache_key)) return;
  (decided.get(r.cache_key) ? accepted : rejected).push(`(${q(r.user_id)},${Number(r.product_id)})`);
});

const sqlCache = fresh.size === 0 ? 'SELECT 1 WHERE false' :
  'INSERT INTO llm_cache (rule_hash, result) VALUES ' +
  [...fresh].map(([k, v]) => `(${q(k)},'{"eligible":${v}}'::jsonb)`).join(',') +
  ' ON CONFLICT (rule_hash) DO NOTHING';

const delPart = rejected.length ? `WITH del AS (DELETE FROM matches WHERE batch_id = $1::uuid AND (user_id, product_id) IN (VALUES ${rejected.join(',')}) RETURNING 1) ` : '';
const updPart = accepted.length ? `UPDATE matches SET stage = 'llm' WHERE batch_id = $1::uuid AND (user_id, product_id) IN (VALUES ${accepted.join(',')})` : '';
const sqlApply = (delPart || updPart) ? (delPart + (updPart || 'SELECT count(*) FROM del')) : 'SELECT 1 WHERE false';

const sqlStats = `WITH c AS (INSERT INTO pipeline_stats (batch_id, stage, pairs) VALUES ($1::uuid, 'llm_calls', ${calls}) RETURNING 1)
INSERT INTO pipeline_stats (batch_id, stage, pairs)
SELECT $1::uuid, 'final', count(*) FROM matches WHERE batch_id = $1::uuid RETURNING stage, pairs`;

return [{ json: { sql_cache: sqlCache, sql_apply: sqlApply, sql_stats: sqlStats, llm_calls: calls, failed_calls: failed,
  borderline_seen: rows.length, judged_eligible: accepted.length, judged_rejected: rejected.length } }];
